16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "postcode")
47	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "identity_key")
71	    private String identityKey;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "household_member_count")
77	    private Integer householdMemberCount;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    public String getAddress() {
92	        return this.address;
93	    }
94	
95	    public void setAddress(String address) {
96	        this.address = address;
97	    }
98	
99	    public String getCity() {
100	        return this.city;
101	    }
102	
103	    public void setCity(String city) {
104	        this.city = city;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = telephone;
121	    }
122	
123	    public String getEmail() {
124	        return this.email;
125	    }
126	
127	    public void setEmail(String email) {
128	        this.email = email;
129	    }
130	
131	    public LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    public LocalDate getBirthDate() {
140	        return this.birthDate;
141	    }
142	
143	    public void setBirthDate(LocalDate birthDate) {
144	        this.birthDate = birthDate;
145	    }
146	
147	    public String getCustomerCode() {
148	        return this.customerCode;
149	    }
150	
151	    public void setCustomerCode(String customerCode) {
152	        this.customerCode = customerCode;
153	    }
154	
155	    public String getHouseholdId() {
156	        return this.householdId;
157	    }
158	
159	    public void setHouseholdId(String householdId) {
160	        this.householdId = householdId;
161	    }
162	
163	    public String getIdentityKey() {
164	        return this.identityKey;
165	    }
166	
167	    public void setIdentityKey(String identityKey) {
168	        this.identityKey = identityKey;
169	    }
170	
171	    public Integer getNamesakeCount() {
172	        return this.namesakeCount;
173	    }
174	
175	    public void setNamesakeCount(Integer namesakeCount) {
176	        this.namesakeCount = namesakeCount;
177	    }
178	
179	    public Integer getHouseholdMemberCount() {
180	        return this.householdMemberCount;
181	    }
182	
183	    public void setHouseholdMemberCount(Integer householdMemberCount) {
184	        this.householdMemberCount = householdMemberCount;
185	    }
186	
187	    public String getMembershipNumber() {
188	        return this.membershipNumber;
189	    }
190	
191	    public void setMembershipNumber(String membershipNumber) {
192	        this.membershipNumber = membershipNumber;
193	    }
194	
195	    public Boolean getPossibleDuplicate() {
196	        return this.possibleDuplicate;
197	    }
198	
199	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
200	        this.possibleDuplicate = possibleDuplicate;
201	    }
202	
203	    public Integer getPossibleDuplicateOf() {
204	        return this.possibleDuplicateOf;
205	    }
206	
207	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
208	        this.possibleDuplicateOf = possibleDuplicateOf;
209	    }
210	
211	    /**
212	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
213	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
214	     * ({@link #householdMemberCount}), and add 3 for tenure over 365 days (whole days from
215	     * {@link #registrationDate} to today).
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
220	            this.registrationDate);
221	    }
222	
223	    /**
224	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
225	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
226	     */
227	    @Transient
228	    public Integer getMembershipLevel() {
229	        return membershipLevel(getMembershipPoints());
230	    }
231	
232	    /** The membership points derived from the given factors: they start at 0, add 2 when
233	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
234	     *  more ({@code householdMemberCount}), and add 3 for tenure over 365 days (whole days from
235	     *  {@code registrationDate} to today). */
236	    private static int membershipPoints(String email, Integer namesakeCount,
237	            Integer householdMemberCount, LocalDate registrationDate) {
238	        int points = 0;
239	        if (email != null && !email.isBlank()) {
240	            points += 2;
241	        }
242	        if (namesakeCount != null && namesakeCount == 0) {
243	            points += 1;
244	        }
245	        if (householdMemberCount != null && householdMemberCount >= 3) {
246	            points += 2;
247	        }
248	        if (registrationDate != null
249	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
250	            points += 3;
251	        }
252	        return points;
253	    }
254	
255	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
256	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
257	    private static int membershipLevel(int points) {
258	        if (points >= 6) {
259	            return 4;
260	        }
261	        if (points >= 4) {
262	            return 3;
263	        }
264	        if (points >= 2) {
265	            return 2;
266	        }
267	        return 1;
268	    }
269	
270	    /**
271	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
272	     * present, otherwise {@code "PHONE"}.
273	     */
274	    @Transient
275	    public String getContactPreference() {
276	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
277	    }
278	
279	    /**
280	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
281	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
282	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
283	     * date to measure against) is available.
284	     */
285	    @Transient
286	    public String getAgeBand() {
287	        if (this.birthDate == null || this.registrationDate == null) {
288	            return null;
289	        }
290	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
291	        if (age < 18) {
292	            return "MINOR";
293	        }
294	        if (age < 65) {
295	            return "ADULT";
296	        }
297	        return "SENIOR";
298	    }
299	
300	    /**
301	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
302	     * {@link #customerCode}, derived on read.
303	     */
304	    @Transient
305	    public Integer getCheckDigit() {
306	        return luhnCheckDigit(this.customerCode);
307	    }
308	
309	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
310	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
311	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
312	        "NSW", new int[] {2000, 2099},
313	        "VIC", new int[] {3000, 3099},
314	        "QLD", new int[] {4000, 4099});
315	
316	    /**
317	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
318	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
319	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
320	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
321	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
322	     */
323	    @Transient
324	    public String getRegion() {
325	        String byPostcode = regionForPostcode(this.postcode);
326	        if (byPostcode != null) {
327	            return byPostcode;
328	        }
329	        if ("Sydney".equals(this.city)) {
330	            return "NSW";
331	        }
332	        if ("Melbourne".equals(this.city)) {
333	            return "VIC";
334	        }
335	        if ("Brisbane".equals(this.city)) {
336	            return "QLD";
337	        }
338	        return "UNKNOWN";
339	    }
340	
341	    /**
342	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
343	     * customer code}: the region segment before the first '-' of the customer code
344	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
345	     * code has been assigned yet.
346	     */
347	    @Transient
348	    public String getLocality() {
349	        if (this.customerCode != null) {
350	            int dash = this.customerCode.indexOf('-');
351	            if (dash > 0) {
352	                return this.customerCode.substring(0, dash);
353	            }
354	        }
355	        return getRegion();
356	    }
357	
358	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
359	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
360	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
361	    public static int[] postcodeRangeForRegion(String region) {
362	        return REGION_POSTCODE_RANGES.get(region);
363	    }
364	
365	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
366	     *  absent, not a 4-digit value, or in no known range. */
367	    private static String regionForPostcode(String postcode) {
368	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
369	            return null;
370	        }
371	        int value = Integer.parseInt(postcode);
372	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
373	            int[] range = entry.getValue();
374	            if (value >= range[0] && value <= range[1]) {
375	                return entry.getKey();
376	            }
377	        }
378	        return null;
379	    }
380	
381	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
382	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
383	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
384	     *  {@code +1}), so a number matches at most one. */
385	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
386	        "+61", 9, "+1", 10);
387	
388	    /**
389	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
390	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
391	     * to the raw value when it is {@code null} or begins with no recognised country code.
392	     */
393	    @Transient
394	    public String getTelephoneDisplay() {
395	        if (this.telephone == null) {
396	            return null;
397	        }
398	        String countryCode = countryCodeOf(this.telephone);
399	        if (countryCode == null) {
400	            return this.telephone;
401	        }
402	        String national = this.telephone.substring(countryCode.length());
403	        StringBuilder grouped = new StringBuilder(countryCode);
404	        for (int i = 0; i < national.length(); i++) {
405	            if (i % 3 == 0) {
406	                grouped.append(' ');
407	            }
408	            grouped.append(national.charAt(i));
409	        }
410	        return grouped.toString();
411	    }
412	
413	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
414	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
415	    public static String countryCodeOf(String telephone) {
416	        if (telephone == null) {
417	            return null;
418	        }
419	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
420	            if (telephone.startsWith(countryCode)) {
421	                return countryCode;
422	            }
423	        }
424	        return null;
425	    }
426	
427	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
428	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
429	     *  {@code +1 => 10}). */
430	    public static Integer nationalNumberLength(String countryCode) {
431	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
432	    }
433	
434	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
435	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
436	     *  digit-free value yields {@code 0}. */
437	    private static int luhnCheckDigit(String value) {
438	        int sum = 0;
439	        boolean doubling = true;
